class Supervisor:
    def __init__(self, workers):
        self.workers = workers      # name -> worker agent
        self.results = {}           # subtask -> result
    def run(self, goal):
        plan = self.decompose(goal)         # supervisor owns the plan
        for step in plan:
            self.results[step.id] = self.dispatch(step)
        return self.integrate(goal, self.results)

def run(self, goal, max_rounds=3):
    plan = self.decompose(goal)
    for _ in range(max_rounds):
        for step in plan:
            self.results[step.id] = self.dispatch(step)
        gaps = self.review(self.results)   # supervisor self-checks
        if not gaps:
            break
        plan = self.replan(goal, gaps)     # fix only what failed
    return self.integrate(goal, self.results)

