def researcher(instruction: str) -> str:
    # a real worker would search; we fake a fact lookup
    return "Paris is the capital of France; ~2.1M people."

def writer(instruction: str) -> str:
    # writer receives the researcher's facts inside its instruction
    return f"Summary -> {instruction.split('Facts: ')[1]}"

WORKERS = {"researcher": researcher, "writer": writer}

def supervisor(goal: str) -> str:
    # 1. decompose
    plan = [("researcher", f"Gather facts for: {goal}"),
            ("writer", "Write a one-line summary. Facts: {facts}")]
    results = {}
    # 2. route each subtask to its worker, filling dependencies
    for name, instruction in plan:
        ctx = instruction.format(facts=results.get("researcher", ""))
        results[name] = WORKERS[name](ctx)
    # 3. integrate
    return results["writer"]

print(supervisor("Describe Paris"))

class Reviewer:
    def check(self, text: str) -> str | None:
        # returns a gap description, or None if the result is good
        return None if "budget" in text.lower() else "missing the budget number"

class FlakyWorker:
    def __init__(self):
        self.calls = 0
    def run(self, instruction: str) -> str:
        self.calls += 1
        # first attempt omits the budget; retry includes it
        if self.calls == 1:
            return "Plan: hire two engineers."
        return "Plan: hire two engineers. Budget: $200k."

def supervisor(goal, worker, reviewer, max_rounds=3):
    instruction = goal
    result = None
    for _ in range(max_rounds):
        result = worker.run(instruction)
        gap = reviewer.check(result)      # supervisor self-checks
        if gap is None:
            return result
        # re-plan: feed the gap back as corrective guidance
        instruction = f"{goal}\nFix this gap: {gap}"
    return result

worker, reviewer = FlakyWorker(), Reviewer()
out = supervisor("Draft a hiring plan", worker, reviewer)
print(out, "| rounds:", worker.calls)

